// Rechaza cualquier llamada que no venga del portal de admisiones.
// Requiere NODE_FUNCTION_ALLOW_BUILTIN=crypto en el contenedor de n8n.
const crypto = require('crypto');
const item = $input.first();
const firma = String(item.json.headers['x-esic-signature'] || '');
// La firma se calcula sobre el cuerpo CRUDO (opción rawBody del webhook),
// no sobre un JSON re-serializado, que cambia espacios y orden de claves.
const crudo = item.binary && item.binary.data
  ? Buffer.from(item.binary.data.data, 'base64')
  : Buffer.from(JSON.stringify(item.json.body));
const esperada = crypto.createHmac('sha256', $env.WEBHOOK_SECRET).update(crudo).digest('hex');
const a = Buffer.from(firma, 'utf8');
const b = Buffer.from(esperada, 'utf8');
// timingSafeEqual lanza si las longitudes difieren: se valida antes.
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('Firma inválida');
}
return $input.all();
